// LockReapableOperations runs the :many query against sqlite.
func (q *sqliteQueries) LockReapableOperations(ctx context.Context, db DBTX, arg LockReapableOperationsParams) ([]LockReapableOperationsRow, error) {
	query := q.lockReapableOperations

	args := make([]any, 0, 4+len(arg.IDs))

	args = append(args, arg.SucceededState)

	args = append(args, arg.FailedState)

	args = append(args, arg.CancelledState)

	args = append(args, arg.RetentionMicroseconds)

	query = strings.Replace(query, "/*SLICE:ids*/?", slicePlaceholders("?", len(arg.IDs)), 1)

	for _, v := range arg.IDs {
		args = append(args, v)
	}

	rows, err := db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, err
	}

	defer func() { _ = rows.Close() }()

	var items []LockReapableOperationsRow

	for rows.Next() {
		var i LockReapableOperationsRow

		if err := rows.Scan(
			&i.ID,
		); err != nil {
			return nil, err
		}

		items = append(items, i)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return items, nil
}

